cd "$ARCHON_HORIZON_ROOT/MainProjects/Algebraic-Jacobian-Challenge" && python3 - <<'PY'
import os,re
def imports(m):
    p=m.replace('.','/')+'.lean'
    return re.findall(r'^import\s+(AlgebraicJacobian[\w.]*)',open(p).read(),re.M) if os.path.exists(p) else []
def clos(r):
    seen,st=set(),[r]
    while st:
        m=st.pop()
        if m not in seen: seen.add(m); st+=imports(m)
    return seen
allm=set()
for d,_,fs in os.walk('AlgebraicJacobian'):
    for f in fs:
        if f.endswith('.lean'): allm.add(os.path.join(d,f)[:-5].replace('/','.'))
root=clos('AlgebraicJacobian'); head=clos('AlgebraicJacobian.Jacobian')
print('total on disk', len(allm))
print('rooted', len(root&allm), 'unrooted', sorted(allm-root))
print('headline reachable', len(head&allm))
PY
